package io.github.jackotom.hongguo.android;
import java.io.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import org.json.*;
/** Real cache facade/policy and captured production Plans; only transport/context are doubles. */
public final class PlaybackResolutionCacheTest {
 static final String SID="1234567890123456789",VID="2345678901234567890",URL="https://v3-reading.qznovelvod.com/shared-resolution.mp4";static int checks,groups;
 interface Run{void run()throws Exception;}static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}static void group(String name,Run run)throws Exception{run.run();groups++;System.out.println("PASS "+name);}
 static JSONObject model(String url,int width,int cap)throws Exception{JSONObject p=new JSONObject().put("url",url).put("vid",VID).put("seriesId",SID).put("source","app").put("requestedQuality","720p").put("width",width).put("height",width*2);if(cap>0)p.put("playbackCeiling",cap);return p;}
 static void deleteTree(File f)throws Exception{if(f.isDirectory())for(File x:Objects.requireNonNull(f.listFiles()))deleteTree(x);Files.deleteIfExists(f.toPath());}
 public static void main(String[]args)throws Exception{
  File root=Files.createTempDirectory("playback-cap-cache-").toFile();PlaybackCache cache=PlaybackCache.get(new android.content.Context(root));
  try{
   group("immutable bounded Plan does not borrow manual same URL and quality variants",()->{NetworkGuard.reset();JSONObject bounded=model(URL,720,1079).put("variants",new JSONArray().put(model(URL+"?low",720,1079)));PlaybackSources.Plan p=PlaybackSources.register(bounded,VID,false);PlaybackSources.register(model(URL,1080,0).put("variants",new JSONArray().put(model(URL+"?high",1080,0))),VID,false);NetworkGuard.outcomes.put(URL,"http401");NetworkGuard.outcomes.put(URL+"?low","clear");NetworkGuard.outcomes.put(URL+"?high","clear");File target=new File(root,"immutable.part");PlaybackSources.download(p,target,64);check(NetworkGuard.attempted.equals(Arrays.asList(URL,URL+"?low")),"only captured bounded variant is tried after colliding registration");check(!NetworkGuard.attempted.contains(URL+"?high"),"uncapped high variant never requested");target.delete();});
   group("manual and each distinct ceiling keep distinct cache and flight identities",()->{check(PlaybackCache.playbackCacheVid(VID,"720p",0).equals(MediaQuality.cacheVid(VID,"720p")),"legacy manual namespace unchanged");Set<String>keys=new HashSet<>();for(int cap:new int[]{0,1079,900})keys.add(PlaybackCache.playbackCacheVid(VID,"720p",cap));check(keys.size()==3,"all caps have independent namespace");});
   group("same URL same quality manual and bounded transfers do not coalesce",()->{NetworkGuard.reset();PlaybackSources.Plan p=PlaybackSources.register(model(URL,720,1079),VID,false);PlaybackSources.register(model(URL,1080,0),VID,false);NetworkGuard.outcomes.put(URL,"clear");NetworkGuard.blocked=URL;NetworkGuard.entered=new CountDownLatch(2);NetworkGuard.allow=new CountDownLatch(1);AtomicReference<File>a=new AtomicReference<>(),b=new AtomicReference<>();AtomicReference<Throwable>failure=new AtomicReference<>();Thread bounded=new Thread(()->{try{a.set(cache.fetchForeground(SID,VID,1,p,"720p"));}catch(Throwable t){failure.compareAndSet(null,t);}}),manual=new Thread(()->{try{b.set(cache.fetch(SID,VID,1,URL,"720p"));}catch(Throwable t){failure.compareAndSet(null,t);}});bounded.start();manual.start();try{check(NetworkGuard.entered.await(5,TimeUnit.SECONDS),"two real transfers entered: no shared flight");}finally{NetworkGuard.allow.countDown();bounded.join(6000);manual.join(6000);NetworkGuard.blocked=null;}check(!bounded.isAlive()&&!manual.isAlive()&&failure.get()==null,"both fixture jobs complete");check(a.get()!=null&&b.get()!=null&&!a.get().equals(b.get()),"bounded and manual files are separate");check(cache.find(SID,VID,1,"720p",1079).equals(a.get()),"bounded file lookup remains exact");check(cache.find(SID,VID,1,"720p").equals(b.get()),"manual file lookup remains exact");});
   group("protection release and invalidation affect only the matching cap",()->{cache.protect(SID,VID,1,"720p",1079);cache.clear();check(cache.find(SID,VID,1,"720p",1079)!=null,"matching cap stays protected");check(cache.find(SID,VID,1,"720p")==null,"manual unprotected cache clears independently");cache.release(SID,VID,1,"720p",900);cache.clear();check(cache.find(SID,VID,1,"720p",1079)!=null,"wrong cap release does not release owned lease");cache.release(SID,VID,1,"720p",1079);cache.invalidate(SID,VID,1,"720p",900);check(cache.find(SID,VID,1,"720p",1079)!=null,"other cap invalidation leaves file");cache.invalidate(SID,VID,1,"720p",1079);check(cache.find(SID,VID,1,"720p",1079)==null,"own cap invalidation removes file");});
   group("background playback prefetch captures immutable bounded plan too",()->{NetworkGuard.reset();PlaybackSources.Plan p=PlaybackSources.register(model(URL,720,900),VID,false);PlaybackSources.register(model(URL,1080,0),VID,false);NetworkGuard.outcomes.put(URL,"clear");File file=cache.fetch(SID,VID,2,p,"720p");check(file.equals(cache.find(SID,VID,2,"720p",900)),"background Plan uses cap namespace");check(cache.find(SID,VID,2,"720p")==null,"no manual namespace pollution");});
   System.out.println("PLAYBACK_RESOLUTION_CACHE_OK groups="+groups+" checks="+checks+" actualCacheFacade=true realFilesystem=true concurrentFlights=isolated networkRequests=0");
  }finally{NetworkGuard.blocked=null;deleteTree(root);}
 }
}
